cublasHandle_t cublas_handle(int target_device, cudaStream_t target_stream) {
    GGML_ASSERT(target_device >= 0 && target_device < ggml_cuda_info().device_count);
    GGML_ASSERT(target_stream != nullptr);
    int slot = 0;
    while (slot < GGML_CUDA_MAX_STREAMS && streams[target_device][slot] != target_stream) ++slot;
    GGML_ASSERT(slot < GGML_CUDA_MAX_STREAMS);
    auto & handle = cublas_handles[target_device][slot];
    if (handle == nullptr) {
        ggml_cuda_set_device(target_device);
        CUBLAS_CHECK(cublasCreate(&handle));
        CUBLAS_CHECK(cublasSetMathMode(handle, CUBLAS_TF32_TENSOR_OP_MATH));
        CUBLAS_CHECK(cublasSetStream(handle, target_stream));
        if (cublas_workspace_sizes[target_device] == 0) {
            const int cc = ggml_cuda_info().devices[target_device].cc;
            cublas_workspace_sizes[target_device] = cc >= GGML_CUDA_CC_HOPPER ? 32 * 1024 * 1024 : 4 * 1024 * 1024;
        }
        CUDA_CHECK(cudaMalloc(&cublas_workspaces[target_device][slot], cublas_workspace_sizes[target_device]));
        CUBLAS_CHECK(cublasSetWorkspace(handle, cublas_workspaces[target_device][slot], cublas_workspace_sizes[target_device]));
    }
    return handle;
}

cublasHandle_t cublas_handle() { return cublas_handle(device, stream()); }

